// Construct Next.js OG render endpoint URL with strict sanitization
const item = $input.first().json;
const baseUrl = $env.NEXT_PUBLIC_APP_URL || 'https://www.avaliasolar.com.br';

const title = encodeURIComponent((item.headline || item.candidate?.title || 'Avalia Solar Notícias').slice(0, 90));
const category = encodeURIComponent((item.category || 'Mercado Livre').slice(0, 30));
const format = 'feed';

const renderUrl = `${baseUrl}/api/social/render-post?title=${title}&category=${category}&format=${format}`;

return [{
  json: {
    ...item,
    render_url: renderUrl,
    media_format: 'feed',
    expected_dimensions: { width: 1080, height: 1350, ratio: '4:5' },
    prepared_at: new Date().toISOString()
  }
}];

// Validate image binary and package media payload
const prev = $('Construct Visual Card URL').first().json;

return [{
  json: {
    status: 'MEDIA_READY',
    candidate: prev.candidate,
    headline: prev.headline,
    full_caption: prev.full_caption,
    image_url: prev.render_url,
    dimensions: prev.expected_dimensions,
    verified_public_url: true,
    rendered_at: new Date().toISOString()
  }
}];
